                        (bits + [UInt8](repeating: 0, count: 8)).withUnsafeBufferPointer { padded in
                            ({
                                let bits = unsafe Span(_unsafeElements: source)
                                var to = unsafe MutableSpan(_unsafeElements: destination)
                                return H.storeCompressed(a, bits: bits, to: &to)
                            })()
                        }
                    }
                )
            }
            mismatches.check(
                portLanes,
                referenceLanes,
                "a: \(describe(a)), bits: \(describe(bits))"
            )
            mismatches.check(
                portResult,
                referenceResult,
                "a: \(describe(a)), bits: \(describe(bits))"
            )
        }
        mismatches.record()
    }
}
